<?php
// DESHACER la aplicación de precios del 14-oct (vuelve precio, comisión, costo, nota de liquidación y precios propios de gestoras).
// Uso (desde Git Bash en el PC de Ernesto):
//   ssh -i ~/.ssh/casa-viva-github-actions -p 65002 u824654880@88.223.85.72 'cd ~/domains/casaviva.company/public_html && wp eval-file - && wp litespeed-purge all' < docs/nexo-business/precios/2026-10-14/deshacer.php
// La caja (nube NEXO) se deshace aparte con deshacer-nube.sql.
$plan = json_decode( base64_decode( '' ), true );
global $wpdb; $n = 0;
foreach ( $plan['OLD'] as $id => $o ) {
	$p = wc_get_product( (int) $id ); if ( ! $p ) { continue; }
	if ( isset( $plan['PRICE'][ $id ] ) ) { $p->set_regular_price( $o['regular'] ); $p->set_sale_price( $o['sale'] ); }
	if ( isset( $plan['COMM'][ $id ] ) ) {
		if ( '' === (string) $o['ctype'] && '' === (string) $o['cval'] ) { $p->delete_meta_data( '_cvd_commission_type' ); $p->delete_meta_data( '_cvd_commission_value' ); }
		else { $p->update_meta_data( '_cvd_commission_type', $o['ctype'] ); $p->update_meta_data( '_cvd_commission_value', $o['cval'] ); }
	}
	if ( isset( $plan['DUD'][ $id ] ) || isset( $plan['FORM'][ $id ] ) ) {
		if ( '' === (string) $o['cost'] ) { $p->delete_meta_data( '_cvd_cost_usd' ); $p->delete_meta_data( '_cvd_cost_source' ); }
		else { $p->update_meta_data( '_cvd_cost_usd', $o['cost'] ); $p->update_meta_data( '_cvd_cost_source', $o['src'] ); }
		$p->update_meta_data( '_cvd_cost_updated_at', gmdate( 'c' ) );
	}
	if ( (int) $id === (int) $plan['NOREPONER'] ) {
		$p->delete_meta_data( '_cvd_no_reponer' ); $p->delete_meta_data( '_cvd_admin_note' );
		if ( $p->get_parent_id() ) { delete_post_meta( $p->get_parent_id(), '_cvd_admin_note' ); }
	}
	$p->save(); $n++;
}
$t = $wpdb->prefix . 'cvd_gestora_prices';
foreach ( $plan['GP'] as $g ) {
	$wpdb->update( $t, array( 'price' => $g['old'], 'updated_at' => current_time( 'mysql', true ) ), array( 'gestora_user_id' => $g['g'], 'product_id' => $g['p'] ), array( '%f', '%s' ), array( '%d', '%d' ) );
	CVD_Gestora_Store::bump_price_version( (int) $g['g'] );
}
wc_delete_product_transients();
echo "Deshecho: $n productos y " . count( $plan['GP'] ) . " precios de gestora.\n";
